import re

_NUM = r'([0-9]+(?:[.,][0-9]+)?)'
_WEEK_RE = re.compile(r'P' + _NUM + r'W')
_DT_RE = re.compile(
    r'P(?:' + _NUM + r'D)?'
    r'(?:T(?=[0-9])(?:' + _NUM + r'H)?(?:' + _NUM + r'M)?(?:' + _NUM + r'S)?)?'
)
_INT_RE = re.compile(r'[0-9]+')


def parse_duration(text: str) -> float:
    if not isinstance(text, str):
        raise ValueError("duration must be a string")

    m = _WEEK_RE.fullmatch(text)
    if m:
        parts = [(m.group(1), 604800)]
    else:
        m = _DT_RE.fullmatch(text)
        if not m:
            raise ValueError(f"invalid ISO 8601 duration: {text!r}")
        parts = []
        for i, unit in zip(range(1, 5), (86400, 3600, 60, 1)):
            val = m.group(i)
            if val is not None:
                parts.append((val, unit))
        if not parts:
            raise ValueError(f"invalid ISO 8601 duration: {text!r}")

    for idx, (val, _) in enumerate(parts):
        if idx < len(parts) - 1 and not _INT_RE.fullmatch(val):
            raise ValueError("only the last component may have a fraction")

    total = 0.0
    for val, unit in parts:
        total += float(val.replace(',', '.')) * unit
    return float(total)
